import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export function createStore(filePath) {
  function load() {
    if (!existsSync(filePath)) return [];
    return JSON.parse(readFileSync(filePath, 'utf8'));
  }

  function save(books) {
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, JSON.stringify(books, null, 2) + '\n');
  }

  return {
    all() {
      return load();
    },

    get(id) {
      return load().find((b) => b.id === id) ?? null;
    },

    add({ title, author, notes = '' }) {
      const books = load();
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        finished: false,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      save(books);
      return book;
    },

    finish(id) {
      const books = load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.finished = true;
      book.finishedAt = new Date().toISOString();
      save(books);
      return book;
    },

    updateNotes(id, notes) {
      const books = load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.notes = notes;
      save(books);
      return book;
    },
  };
}

