import { createServer } from 'node:http';
import { createStore } from './store.mjs';

const escape = (s) =>
  String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

const page = (title, body) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; line-height: 1.5; }
  h1 { font-size: 1.5rem; } h2 { font-size: 1.1rem; margin-top: 2rem; }
  a { color: #0645ad; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: 0.5rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  .author { color: #666; font-size: 0.9rem; }
  form.inline { display: inline; }
  label { display: block; margin-top: 0.75rem; font-weight: 600; }
  input[type=text], textarea { width: 100%; padding: 0.4rem; font: inherit; box-sizing: border-box; }
  button { margin-top: 0.75rem; padding: 0.4rem 0.9rem; font: inherit; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f8f8f8; padding: 0.75rem; border-radius: 4px; }
  .muted { color: #888; font-size: 0.9rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;

const bookItem = (book) => `<li>
  <span><a href="/book/${book.id}">${escape(book.title)}</a>
  <span class="author">by ${escape(book.author)}</span></span>
  ${
    book.finished
      ? ''
      : `<form class="inline" method="post" action="/book/${book.id}/finish"><button>Finished</button></form>`
  }
</li>`;

const bookList = (books) =>
  books.length
    ? `<ul class="books">${books.map(bookItem).join('\n')}</ul>`
    : `<p class="muted">Nothing here yet.</p>`;

function homePage(store) {
  const books = store.all();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  return page(
    'My books',
    `<h1>My books</h1>
<h2>Currently reading</h2>
${bookList(reading)}
<h2>Finished</h2>
${bookList(finished)}
<h2>Add a book</h2>
<form method="post" action="/books">
  <label for="title">Title</label>
  <input type="text" id="title" name="title" required>
  <label for="author">Author</label>
  <input type="text" id="author" name="author" required>
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" rows="4"></textarea>
  <button>Add book</button>
</form>`
  );
}

function bookPage(book) {
  return page(
    book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${escape(book.title)}</h1>
<p class="author">by ${escape(book.author)}</p>
<p class="muted">${
      book.finished
        ? `Finished ${escape(book.finishedAt.slice(0, 10))}`
        : 'Currently reading'
    }</p>
${
  book.finished
    ? ''
    : `<form class="inline" method="post" action="/book/${book.id}/finish"><button>Mark as finished</button></form>`
}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="muted">No notes yet.</p>'}
<form method="post" action="/book/${book.id}/notes">
  <label for="notes">Edit notes</label>
  <textarea id="notes" name="notes" rows="6">${escape(book.notes)}</textarea>
  <button>Save notes</button>
</form>`
  );
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 1e6) reject(new Error('body too large'));
    });
    req.on('end', () => resolve(new URLSearchParams(body)));
    req.on('error', reject);
  });
}

export function createApp(store) {
  return createServer(async (req, res) => {
    const html = (status, body) =>
      res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' }).end(body);
    const redirect = (to) => res.writeHead(303, { location: to }).end();
    const notFound = () => html(404, page('Not found', '<h1>Book not found</h1><p><a href="/">&larr; All books</a></p>'));

    try {
      const url = new URL(req.url, 'http://localhost');
      const bookMatch = url.pathname.match(/^\/book\/([0-9a-f-]+)(\/(finish|notes))?$/);

      if (req.method === 'GET' && url.pathname === '/') {
        return html(200, homePage(store));
      }

      if (req.method === 'POST' && url.pathname === '/books') {
        const form = await readForm(req);
        const title = (form.get('title') ?? '').trim();
        const author = (form.get('author') ?? '').trim();
        if (!title || !author) return html(400, page('Error', '<h1>Title and author are required</h1><p><a href="/">&larr; Back</a></p>'));
        store.add({ title, author, notes: (form.get('notes') ?? '').trim() });
        return redirect('/');
      }

      if (bookMatch) {
        const [, id, , action] = bookMatch;
        if (req.method === 'GET' && !action) {
          const book = store.get(id);
          return book ? html(200, bookPage(book)) : notFound();
        }
        if (req.method === 'POST' && action === 'finish') {
          return store.finish(id) ? redirect(req.headers.referer?.endsWith(`/book/${id}`) ? `/book/${id}` : '/') : notFound();
        }
        if (req.method === 'POST' && action === 'notes') {
          const form = await readForm(req);
          return store.updateNotes(id, (form.get('notes') ?? '').trim()) ? redirect(`/book/${id}`) : notFound();
        }
      }

      return notFound();
    } catch {
      return html(500, page('Error', '<h1>Something went wrong</h1><p><a href="/">&larr; All books</a></p>'));
    }
  });
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const port = process.env.PORT ?? 3000;
  const store = createStore(new URL('../data/books.json', import.meta.url).pathname);
  createApp(store).listen(port, () => {
    console.log(`Book tracker running at http://localhost:${port}`);
  });
}

