import { describe, it, expect, beforeEach } from 'vitest';
import { mkdtempSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createStore } from '../src/store.mjs';

describe('store', () => {
  let store;
  let file;

  beforeEach(() => {
    file = join(mkdtempSync(join(tmpdir(), 'books-')), 'books.json');
    store = createStore(file);
  });

  it('starts empty when the file does not exist', () => {
    expect(store.all()).toEqual([]);
  });

  it('adds a book and persists it to the JSON file', () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'sandy' });
    expect(book.finished).toBe(false);
    const onDisk = JSON.parse(readFileSync(file, 'utf8'));
    expect(onDisk).toHaveLength(1);
    expect(onDisk[0]).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'sandy' });
  });

  it('survives a restart (new store instance reads the same file)', () => {
    store.add({ title: 'Dune', author: 'Frank Herbert' });
    const reopened = createStore(file);
    expect(reopened.all()).toHaveLength(1);
  });

  it('marks a book as finished', () => {
    const { id } = store.add({ title: 'Dune', author: 'Frank Herbert' });
    const finished = store.finish(id);
    expect(finished.finished).toBe(true);
    expect(finished.finishedAt).toBeTruthy();
    expect(store.get(id).finished).toBe(true);
  });

  it('updates notes', () => {
    const { id } = store.add({ title: 'Dune', author: 'Frank Herbert' });
    store.updateNotes(id, 'the spice must flow');
    expect(store.get(id).notes).toBe('the spice must flow');
  });

  it('returns null for unknown ids', () => {
    expect(store.get('nope')).toBeNull();
    expect(store.finish('nope')).toBeNull();
    expect(store.updateNotes('nope', 'x')).toBeNull();
  });
});

